h_regions = [(0, 2), (4, 6), (8, 10), (12, 14)]
v_regions = [(0, 2), (4, 6), (8, 10), (12, 14)]

demo_out = [
    [8, 8, 1, 8],
    [8, 8, 1, 8],
    [8, 8, 1, 8],
    [8, 1, 8, 1],
]

def get_6_positions(r_start, r_end, c_start, c_end):
    positions = []
    for r in range(r_start, r_end + 1):
        for c in range(c_start, c_end + 1):
            if demo_in[r][c] == 6:
                positions.append((r, c))
    return positions

# For each output cell, print the positions of 6s
for row, (r_start, r_end) in enumerate(h_regions):
    for col, (c_start, c_end) in enumerate(v_regions):
        out_val = demo_out[row][col]
        positions = get_6_positions(r_start, r_end, c_start, c_end)
        print(f"Output {out_val} at ({row},{col}): 6s at {positions}")

